import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, mix, color, texture, sin, fract, dot, vec2 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  const root = new THREE.Group();
  root.name = 'hub-collection-card-0-label';

  const inner = new THREE.Group();
  root.add(inner);

  const palette = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  // Aspect derived from atlas source rect 512x320
  const width = 1.5;
  const height = width * (320 / 512);

  const geometry = new THREE.PlaneGeometry(width, height, 1, 1);
  const material = new MeshStandardNodeMaterial({
    roughness: 0.56,
    metalness: 0.38,
  });

  const inkColor = color(palette.ink);
  const surfaceColor = color(palette.surface);
  const accentColor = color(palette.accent);

  // Engineered gradient (vertical) + fine procedural grain — no soft pastel blur.
  const gradient = mix(inkColor, surfaceColor, uv().y);
  const grain = fract(
    sin(dot(uv(), vec2(12.9898, 78.233))).mul(43758.5453)
  )
    .sub(0.5)
    .mul(0.035);
  const baseColorNode = gradient.add(grain);

  material.colorNode = baseColorNode;
  // Subtle accent glow at low intensity, kept under the brightness cap and <=10% of frame.
  material.emissiveNode = accentColor.mul(0.04);

  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(0, 0, 0);
  inner.add(mesh);

  let loadedTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader
      .loadTexture(config.imageUrl)
      .then((tex) => {
        loadedTexture = tex;
        tex.colorSpace = THREE.SRGBColorSpace;
        material.colorNode = mix(baseColorNode, texture(tex, uv()).rgb, 0.82);
        material.needsUpdate = true;
      })
      .catch(() => {
        // keep procedural gradient fallback — no HTTP/dom fallback allowed
      });
  }

  // Text — render spec copy verbatim via MSDF atlas, never invented copy.
  const items =
    config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem =
    items.find((i) => i.role === 'headline') ?? { text: 'Collection 3' };

  const label = ctx.fontAtlas.createText(headlineItem.text ?? 'Collection 3', {
    fontSize: headlineItem.typography?.fontSize ?? 39,
    color: palette.paper,
    align: 'center',
  });
  label.position.set(0, 0, 0.015);
  inner.add(label);

  // Weighted-settle entrance only — static composition, no idle loop, no interactivity.
  inner.position.set(0, 0.12, 0);
  inner.scale.set(0.96, 0.96, 0.96);

  const timeline = gsap.timeline();
  timeline.to(inner.position, {
    y: 0,
    duration: 0.9,
    ease: 'power4.out',
  });
  timeline.to(
    inner.scale,
    {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.9,
      ease: 'power4.out',
    },
    0
  );

  // No cinematic primitives specified for this element; loop kept for spec fidelity.
  const primitiveHandles = [];
  const primitiveList = config.cinematicPrimitives ?? [];
  for (const prim of primitiveList) {
    const applyFn = ctx.primitives?.[prim.name];
    if (typeof applyFn === 'function') {
      const handle = applyFn(inner, prim.params ?? {});
      if (handle) primitiveHandles.push(handle);
    }
  }

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    timeline.kill();
    for (const handle of primitiveHandles) {
      try {
        handle.cleanup?.();
      } catch (e) {
        // no-op
      }
    }
    geometry.dispose();
    material.dispose();
    if (loadedTexture) {
      loadedTexture.dispose?.();
    }
    if (label?.userData?.cleanup) {
      label.userData.cleanup();
    } else if (label?.geometry) {
      label.geometry.dispose?.();
      label.material?.dispose?.();
    }
  };

  return root;
}
